{"content":"/* Party-facing dispute form. W15 layout pass: the Ryde app's canvas rhythm —
   720px shell, white step cards floating on the pastel paper, pill eyebrow
   chip, sticky in-card action bar. Colours stay the W10 brand tokens. */

:root {
  --ink: #31373E;
  --muted: #5A6470;
  --line: #E5E0DC;
  --paper: #F7DDE3;
  --card: #ffffff;
  --accent: #E93864;
  --accent-ink: #ffffff;
  --error: #C0392B;
  --ok: #1EB848;
  --tint: #FFF0F3;
  --float-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: Poppins, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
}

.party-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 5rem;
}

.party-header .eyebrow {
  display: inline-block;
  margin: 0;
  padding: 0.35rem 0.9rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--accent);
  background: var(--tint);
  border: 1px solid var(--accent);
  border-radius: 9999px;
}

.party-header h1 {
  margin: 0.25rem 0 0.5rem;
  font-size: 2.25rem;
  font-weight: 600;
}

.intro {
  margin: 0 0 0.25rem;
  color: var(--muted);
}

.demo-note {
  margin: 0 0 1.5rem;
  padding: 0.6rem 0.9rem;
  font-size: 0.85rem;
  color: var(--muted);
  background: var(--tint);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.step {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: var(--float-shadow);
}

.step h2 {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0 0 0.9rem;
  font-size: 1.15rem;
  font-weight: 600;
}

.step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.9rem;
}

.hint {
  margin: -0.4rem 0 0.9rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.option-grid {
  display: grid;
  gap: 0.6rem;
}

.option-card {
  text-align: left;
  width: 100%;
  padding: 1rem 1.1rem;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  font: inherit;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

.option-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
  box-shadow: var(--float-shadow);
}

.option-card.selected {
  background: var(--tint);
  border: 2px solid var(--accent);
  box-shadow: none;
}

.choice-options {
  display: flex;
  gap: 0.6rem;
  margin-bottom: 0.6rem;
}

.choice-button {
  flex: 1;
  border: 2px solid var(--line);
  background: var(--card);
  color: var(--ink);
  font-weight: 400;
}

.choice-button:hover {
  border-color: var(--accent);
}

.choice-button.selected {
  border-width: 3px;
  border-color: var(--accent);
  font-weight: 600;
}

.elaborate {
  margin-top: 0.6rem;
}

.trip-card strong {
  display: block;
}

.trip-meta {
  display: block;
  color: var(--muted);
  font-size: 0.85rem;
}

.loading {
  color: var(--muted);
}

.field {
  margin-bottom: 1rem;
}

.field label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.3rem;
}

.field-note {
  font-weight: 400;
  color: var(--muted);
  font-size: 0.8rem;
}

textarea,
input[type="text"],
input[type="number"] {
  width: 100%;
  padding: 0.7rem 0.9rem;
  border: 1px solid var(--line);
  border-radius: 14px;
  font: inherit;
  resize: vertical;
}

textarea:focus,
input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  box-shadow: 0 0 0 4px var(--tint);
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.step-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.6rem;
  margin-top: 1rem;
  padding: 0.75rem 0 0.25rem;
  position: sticky;
  bottom: 0;
  background: var(--card);
  border-top: 1px solid var(--line);
  border-radius: 0 0 20px 20px;
}

button {
  font: inherit;
  font-weight: 600;
  padding: 0.7rem 1.5rem;
  border-radius: 29px;
  border: 1px solid var(--line);
  background: var(--card);
  cursor: pointer;
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button:not(:disabled):hover {
  filter: brightness(0.97);
}

.error {
  color: var(--error);
  margin: 0.6rem 0 0;
}

.outcome-message {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.9rem 1rem;
}

.reference {
  color: var(--muted);
}

.reference strong {
  color: var(--ink);
  letter-spacing: 0.03em;
}

.status-line {
  color: var(--muted);
  font-size: 0.9rem;
}

#question-boxes .field label {
  white-space: pre-line;
}
